<?php $editing=!empty($record);$v=fn($field,$default='')=>old($field,$record[$field]??$default); ?>
<section class="page-header"><div><a class="back-link" href="<?= url('staff') ?>"><i class="fa-solid fa-arrow-left"></i> Back to staff</a><h1><?= $editing?'Edit staff member':'Add staff member' ?></h1><p><?= $editing?'Update employment, payroll and access information.':'Create the employee profile and secure staff portal credentials together.' ?></p></div></section>
<section class="panel form-panel"><form class="entity-form" method="post" action="<?= $editing?url('staff/'.$record['id']):url('staff') ?>"><?= csrf_field() ?><div class="form-section"><h3>Login and identity</h3><div class="form-grid"><label>Full name *<input name="name" value="<?= e($v('name')) ?>" required maxlength="150"></label><label>Employee code *<input name="employee_code" value="<?= e($v('employee_code')) ?>" required placeholder="RM-EMP-006"></label><label>Email *<input type="email" name="email" value="<?= e($v('email')) ?>" required></label><label>Phone *<input type="tel" name="phone" value="<?= e($v('phone')) ?>" required></label><label class="wide"><?= $editing?'New temporary password':'Temporary password *' ?><input type="password" name="password" minlength="10" <?= $editing?'':'required' ?> placeholder="<?= $editing?'Leave blank to keep current password':'Staff must change it on first login' ?>"><small>At least 10 characters. A new temporary password requires a change on next login.</small></label><?php if($editing):?><label>Login status<select name="user_status"><?php foreach(['active','inactive','locked'] as $s):?><option value="<?= $s ?>" <?= $v('user_status')===$s?'selected':'' ?>><?= e(ucfirst($s)) ?></option><?php endforeach;?></select></label><label>Employment status<select name="employment_status"><?php foreach(['active','inactive','resigned'] as $s):?><option value="<?= $s ?>" <?= $v('employment_status')===$s?'selected':'' ?>><?= e(ucfirst($s)) ?></option><?php endforeach;?></select></label><?php endif;?></div></div>
<div class="form-section"><h3>Employment</h3><div class="form-grid"><label>Department<select name="department_id"><option value="">Select department</option><?php foreach($departments as $x):?><option value="<?= $x['id'] ?>" <?= (string)$v('department_id')===(string)$x['id']?'selected':'' ?>><?= e($x['name']) ?></option><?php endforeach;?></select></label><label>Designation<select name="designation_id"><option value="">Select designation</option><?php foreach($designations as $x):?><option value="<?= $x['id'] ?>" <?= (string)$v('designation_id')===(string)$x['id']?'selected':'' ?>><?= e($x['name']) ?></option><?php endforeach;?></select></label><label>Reporting manager<select name="reporting_manager_id"><option value="">No manager</option><?php foreach($managers as $x):?><option value="<?= $x['id'] ?>" <?= (string)$v('reporting_manager_id')===(string)$x['id']?'selected':'' ?>><?= e($x['name']) ?></option><?php endforeach;?></select></label><label>Shift<select name="shift_id"><option value="">Select shift</option><?php foreach($shifts as $x):?><option value="<?= $x['id'] ?>" <?= (string)$v('shift_id')===(string)$x['id']?'selected':'' ?>><?= e($x['name']) ?></option><?php endforeach;?></select></label><label>Joining date *<input type="date" name="joining_date" value="<?= e($v('joining_date',date('Y-m-d'))) ?>" required></label><label>Employment type<select name="employment_type"><?php foreach(['full_time'=>'Full time','part_time'=>'Part time','contract'=>'Contract','intern'=>'Intern'] as $key=>$label):?><option value="<?= $key ?>" <?= $v('employment_type','full_time')===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select></label><label>Monthly salary *<input type="number" step="0.01" min="0" name="monthly_salary" value="<?= e($v('monthly_salary')) ?>" required></label><label>Daily salary rate<input type="number" step="0.01" min="0" name="daily_salary_rate" value="<?= e($v('daily_salary_rate')) ?>"></label><label>Emergency contact<input name="emergency_contact" value="<?= e($v('emergency_contact')) ?>"></label><label>Work location<input name="work_location" value="<?= e($v('work_location','Head Office')) ?>"></label><label class="wide">Address<textarea name="address" rows="3"><?= e($v('address')) ?></textarea></label></div></div><div class="form-section"><h3>Banking & KYC <small>(restricted to authorised roles)</small></h3><div class="form-grid"><label>Bank name<input name="bank_name" value="<?= e($v('bank_name')) ?>"></label><label>Account number<input name="bank_account_number" value="<?= e($v('bank_account_number')) ?>"></label><label>IFSC<input name="ifsc" value="<?= e($v('ifsc')) ?>"></label><label>PAN<input name="pan" value="<?= e($v('pan')) ?>"></label><label class="wide">Aadhaar <?= $editing?'(leave blank to retain encrypted value)':'' ?><input name="aadhaar" inputmode="numeric" maxlength="12"><small>Stored encrypted; never displayed in list views.</small></label></div></div><div class="form-actions"><a class="button button-secondary" href="<?= url('staff') ?>">Cancel</a><button class="button button-primary"><i class="fa-solid fa-floppy-disk"></i> <?= $editing?'Save staff profile':'Create staff and login' ?></button></div></form></section>
